#include <cassert>
#include <cstdio>
#include "device_reset.h"

int main() {
  assert(bridge_reset::waitSlice(100, 300000, 100, 1000) == 1000);
  assert(bridge_reset::waitSlice(100, 300000, 300099, 1000) == 1);
  assert(bridge_reset::waitSlice(100, 300000, 300100, 1000) == 0);
  assert(bridge_reset::waitSlice(100, 300000, 200, 0) == 299900);
  bridge_reset::ClientState state;
  assert(state.ready());
  unsigned reads = 0, consumes = 0, failures = 0, rebuilds = 0;
  unsigned cachedWidth = 1280;
  const auto receive = [&](bool ready, HRESULT backend) {
    return bridge_reset::receive([&]() { return ready; },
      [&]() { ++reads; return backend; }, [&]() { ++consumes; },
      [&]() { ++failures; state.failTransport(); });
  };
  state.begin();
  assert(!state.ready());
  assert(state.complete(receive(true, D3DERR_INVALIDCALL), [&]() { ++rebuilds; cachedWidth = 1920; }) == D3DERR_INVALIDCALL);
  assert(reads == 1 && consumes == 1 && !failures && !rebuilds && cachedWidth == 1280);
  assert(state.cooperative(D3D_OK) == D3DERR_DEVICENOTRESET);
  assert(state.cooperative(D3DERR_DEVICELOST) == D3DERR_DEVICELOST);
  // A second failed attempt must remain retryable, with no implicit resources rebuilt.
  state.begin();
  assert(state.complete(receive(true, E_OUTOFMEMORY), [&]() { ++rebuilds; }) == E_OUTOFMEMORY);
  assert(!state.ready() && !state.transportFailed() && !rebuilds);
  state.begin();
  assert(state.complete(receive(true, D3D_OK), [&]() { ++rebuilds; cachedWidth = 1920; }) == D3D_OK);
  assert(state.ready() && rebuilds == 1 && cachedWidth == 1920);
  assert(state.cooperative(D3D_OK) == D3D_OK);
  // Timeout must leave the reply/data queue untouched and permanently stop this session.
  state.begin();
  const auto beforeReads = reads, beforeConsumes = consumes;
  assert(state.complete(receive(false, D3D_OK), [&]() { ++rebuilds; cachedWidth = 2048; }) == D3DERR_DEVICELOST);
  assert(reads == beforeReads && consumes == beforeConsumes && failures == 1);
  assert(!state.ready() && state.transportFailed() && cachedWidth == 1920 && rebuilds == 1);
  assert(state.complete(D3D_OK, [&]() { ++rebuilds; }) == D3DERR_DEVICELOST);
  assert(state.cooperative(D3D_OK) == D3DERR_DEVICELOST);
  assert(rebuilds == 1);
  puts("PASS: failed reset, repeated failure, success retry, preserved cache, timeout without read/pop, late success rejected");
}
